	    Discharge entity = new Discharge();
            entity.setDischargeId( event.getDischargeId() );
            entity.setDischargeDateTime( event.getDischargeDateTime() );
            entity.setDisposition( event.getDisposition() );
	    
    	// ------------------------------------------
